// Entrada del webhook: valida token y archivo ANTES de gastar tokens del LLM.
const MAX_BYTES = 10 * 1024 * 1024;
const MIME_PERMITIDOS = ['application/pdf', 'image/png', 'image/jpeg', 'image/jpg'];
// URL del backend: solo desde la configuración del servidor, nunca desde el request
// (si viniera del navegador, cualquiera podría desviar el token del usuario a otro host).
let apiBaseUrl = 'http://host.docker.internal:8000';
try {
  apiBaseUrl = $env.MEDIFLOW_API_BASE_URL || apiBaseUrl;
} catch (e) {
  // N8N_BLOCK_ENV_ACCESS_IN_NODE=true: se usa el valor por defecto.
}

const webhook = $('Ingesta Webhook').first();
const json = webhook.json || {};
const headers = json.headers || {};

const authHeader = headers.authorization || headers.Authorization || '';
const token = authHeader.replace(/^Bearer\s+/i, '').trim() || String((json.body || {}).token || json.token || '').trim();
if (!token) {
  throw new Error('No se recibió token de autenticación (JWT) desde el frontend');
}

const binary = webhook.binary || {};
const binaryKey = Object.keys(binary)[0];
if (!binaryKey) {
  throw new Error('No se recibió ningún archivo en el webhook');
}
const mime = (binary[binaryKey].mimeType || '').toLowerCase();
if (!MIME_PERMITIDOS.includes(mime)) {
  throw new Error('Formato no admitido (' + mime + '): use PDF, PNG o JPG');
}

// Convierte a base64 aquí: es el único nodo cuya entrada trae el binario del webhook.
// En n8n 2.x binary.data.data es solo una referencia al disco, no el contenido.
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
if (buffer.length > MAX_BYTES) {
  throw new Error('El archivo supera el límite de 10 MB');
}

return [{
  json: {
    // Siempre lo genera el servidor: un único responsable evita colisiones y rutas raras en OCI.
    documento_id: 'DOC-' + (typeof crypto !== 'undefined' && crypto.randomUUID
      ? crypto.randomUUID()
      : Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12)),
    access_token: token,
    api_base_url: apiBaseUrl.replace(/\/+$/, ''),
    archivo_base64: buffer.toString('base64'),
    archivo_mime: mime
  },
  binary
}];

const prep = $('Preparar corrida').first();
// El base64 no viaja por la rama de IA: solo lo lee 'Armar IngestPayload' desde 'Preparar corrida'
const { archivo_base64, ...json } = prep.json;
return [{ json, binary: prep.binary }];

// Arma el prompt de triaje (texto o imagen). Todo lo que se agrega aquí se paga en tokens
// en CADA documento: mantenerlo compacto.
const MAX_CHARS = 24000;   // ~6-8k tokens: suficiente para cualquier documento clínico típico
const TAIL_CHARS = 4000;   // se conserva el final (conclusiones / indicaciones al alta)

function listFrom(name) {
  try {
    const items = $(name).all();
    if (items.length === 1 && Array.isArray(items[0].json)) return items[0].json;
    return items.map((i) => i.json);
  } catch {
    return [];
  }
}

function limpiarTexto(raw) {
  const texto = String(raw || '')
    .replace(/\r/g, '')
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (texto.length <= MAX_CHARS) return texto;
  return texto.slice(0, MAX_CHARS - TAIL_CHARS) + '\n[...texto omitido...]\n' + texto.slice(-TAIL_CHARS);
}

// Bloque de detalle_clinico de cada tipo semilla (= BLOQUE_POR_TIPO del backend). Solo se
// envía el de los tipos activos.
const BLOQUES = {
  RECETA: 'medicamentos:[{nombre,dosis,duracion_tratamiento}]',
  LABORATORIO: 'examenes_y_laboratorio:{estudio_solicitado,conclusiones_o_hallazgos,paneles:[{nombre_panel,parametros:[{nombre,valor,unidad,rango_referencia,alterado}]}]}',
  IMAGENES: 'informe_imagenologico:{tecnica,antecedentes,hallazgos,impresion_diagnostica}',
  SOLICITUD_PROCEDIMIENTO: 'solicitud_procedimiento:{procedimiento_solicitado,indicacion_clinica,antecedentes,fecha_solicitud}',
  EPICRISIS: 'procedimientos_e_internacion:{fecha_ingreso,fecha_alta,resumen_evolucion,antecedentes_relevantes,procedimientos_realizados:[]}',
  INTERCONSULTA: 'interconsulta:{especialidad_destino,establecimiento_destino,motivo_interconsulta,antecedentes_clinicos}',
  ANATOMIA_PATOLOGICA: 'anatomia_patologica:{tipo_muestra,descripcion_macroscopica,descripcion_microscopica,diagnostico_histopatologico,malignidad}',
  PROTOCOLO_OPERATORIO: 'protocolo_operatorio:{fecha_cirugia,cirugia_realizada,diagnostico_preoperatorio,tecnica,hallazgos_intraoperatorios,complicaciones,muestras_enviadas}',
  NOTA_ATENCION: 'nota_atencion_ambulatoria:{motivo_consulta,antecedentes,anamnesis,examen_fisico,diagnostico_referencia,diagnostico_atencion,indicaciones}',
};

const tipos = listFrom('GET tipos activos')
  .map((t) => '- ' + t.codigo + ' (' + t.nombre + '): ' + t.descripcion +
    (BLOQUES[t.codigo] ? '\n  bloque ' + BLOQUES[t.codigo] : '') +
    (t.campos_extraccion ? '\n  campos_adicionales ' + JSON.stringify(t.campos_extraccion) : ''))
  .join('\n');
const colas = listFrom('GET colas activas')
  .map((c) => '- ' + c.codigo + ' (' + c.nombre + ')' + (c.notificar_inmediato ? ' [NOTIFICAR]' : '') +
    ': ' + c.descripcion_semantica)
  .join('\n');

const item = $input.first();
const esImagen = Boolean(item.json.es_imagen_normalizada);
const documento = esImagen ? '(ver imagen adjunta)' : limpiarTexto(item.json.text);

const prompt = `Eres MediFlow-AI, motor de triaje de documentos clínicos. Responde SOLO un objeto JSON válido, sin markdown.

REGLAS
- tipo_documento y destino_principal: EXACTAMENTE un "codigo" de TIPOS y de COLAS. No inventes valores.
- No inventes datos: si falta, null. cie10_sugerido solo con evidencia.
- nivel_prioridad: Rutina | Prioritario | Urgente. Riesgo vital: Urgente.
- score_confianza_clasificacion (0-1) = tu certeza real. Ilegible, dudoso o sin paciente/tipo: score < 0.7 y requiere_auditoria_humana = true.
- Cola [NOTIFICAR]: notificacion_generada = {canal, mensaje (máx. 120 caracteres)}; si no, null.
- detalle_clinico: SOLO el "bloque" del tipo elegido (tipo sin bloque: {}); no incluyas otros. Si el tipo trae campos_adicionales (JSON Schema), agrega detalle_clinico.campos_adicionales.
- Copia valores literalmente; justificacion_enrutamiento en máx. 200 caracteres.

SALIDA
{"clasificacion":{"tipo_documento":"","especialidad":null,"nivel_prioridad":"","score_confianza_clasificacion":0},"datos_generales":{"paciente":{"rut":null,"nombre":null,"edad":null},"medico_solicitante":{"rut":null,"nombre":null,"matricula":null},"diagnostico_principal":null,"cie10_sugerido":null},"detalle_clinico":{},"decision_enrutamiento":{"destino_principal":"","requiere_auditoria_humana":false,"justificacion_enrutamiento":"","notificacion_generada":null}}

TIPOS
${tipos || '(vacío: usa OTRO, score < 0.7 y requiere_auditoria_humana = true)'}

COLAS
${colas || '(vacío: requiere_auditoria_humana = true)'}

DOCUMENTO
${documento}`;

return [{
  json: { prompt, modo: esImagen ? 'imagen' : 'texto' },
  binary: esImagen ? item.binary : undefined
}];

const item = $input.first();
let binary = item.binary;
if (!binary || Object.keys(binary).length === 0) {
  try {
    binary = $('Preparar corrida').first().binary;
  } catch (e) {
    binary = {};
  }
}
const binaryKeys = Object.keys(binary || {});
if (binaryKeys.length === 0) {
  throw new Error('No se encontró ningún archivo binario en la entrada de imagen.');
}
const binaryPropertyName = binaryKeys[0];
const binaryData = binary[binaryPropertyName];

let mimeType = binaryData.mimeType || 'image/jpeg';
if (mimeType.includes('jfif') || binaryData.fileExtension === 'jfif') {
  mimeType = 'image/jpeg';
}

return {
  json: {
    ...item.json,
    es_imagen_normalizada: true,
    mime_type_detectado: mimeType
  },
  binary: {
    data: {
      ...binaryData,
      mimeType: mimeType,
      fileExtension: mimeType.split('/')[1] || 'jpg'
    }
  }
};

/**
 * Construye el IngestPayload para FastAPI a partir de la respuesta del LLM.
 * Regla: nunca rellenar con valores inventados; un dato faltante va null y, si es clave,
 * el documento se marca para auditoría humana (el backend decide el estado final).
 */
function parseLlm(raw) {
  if (raw && typeof raw === 'object' && raw.clasificacion) return raw;
  const text = typeof raw === 'string' ? raw : raw?.text || raw?.output || '';
  const match = String(text).match(/\{[\s\S]*\}/);
  if (!match) return {};
  try {
    return JSON.parse(match[0]);
  } catch {
    return {};
  }
}

function listFrom(nodeName) {
  try {
    const items = $(nodeName).all();
    if (items.length === 1 && Array.isArray(items[0].json)) return items[0].json;
    return items.map((i) => i.json);
  } catch {
    return [];
  }
}

const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});

const item = $input.first();
const prep = $('Preparar corrida').first();
const llm = parseLlm(item.json);
const respuestaValida = Object.keys(llm).length > 0;

// 1. Archivo (base64 calculado en 'Preparar corrida')
const archivoBase64 = prep.json.archivo_base64 || '';
if (!archivoBase64) {
  throw new Error('No hay archivo en base64 desde Preparar corrida');
}
const mime = prep.json.archivo_mime || '';
const tipoArchivo = mime.includes('pdf') ? 'PDF' : mime.includes('png') ? 'PNG' : 'JPG';

// 2. Tipo y cola: deben ser códigos del catálogo (se acepta el nombre por tolerancia)
const tiposCatalogo = listFrom('GET tipos activos');
const colasCatalogo = listFrom('GET colas activas');
const clasificacion = obj(llm.clasificacion);
const decision = obj(llm.decision_enrutamiento);

const rawTipo = String(clasificacion.tipo_documento || '').trim();
const tipoPorNombre = tiposCatalogo.find((t) => t.nombre === rawTipo);
let tipoCodigo = tipoPorNombre ? tipoPorNombre.codigo : rawTipo || 'OTRO';
if (tiposCatalogo.length && !tiposCatalogo.some((t) => t.codigo === tipoCodigo)) {
  tipoCodigo = 'OTRO';
}

let destino = String(decision.destino_principal || '').trim();
const colaPorNombre = colasCatalogo.find((c) => c.nombre === destino);
if (colaPorNombre) destino = colaPorNombre.codigo;
let destinoInvalido = false;
if (!colasCatalogo.some((c) => c.codigo === destino)) {
  destinoInvalido = true;
  destino = colasCatalogo.some((c) => c.codigo === 'Ficha_Clinica')
    ? 'Ficha_Clinica'
    : (colasCatalogo[0] && colasCatalogo[0].codigo) || 'Ficha_Clinica';
}

const prioridad = ['Rutina', 'Prioritario', 'Urgente'].includes(clasificacion.nivel_prioridad)
  ? clasificacion.nivel_prioridad
  : 'Prioritario';

// Sin score explícito se asume 0: un dato ausente nunca debe saltarse la auditoría.
const scoreNum = Number(clasificacion.score_confianza_clasificacion);
const score = Number.isFinite(scoreNum) ? Math.min(1, Math.max(0, scoreNum)) : 0;

// 3. Datos generales
const datos = obj(llm.datos_generales);
const pac = obj(datos.paciente);
const med = obj(datos.medico_solicitante);
const edad = pac.edad != null && Number.isFinite(Number(pac.edad)) ? Math.round(Number(pac.edad)) : null;

const paciente = { rut: pac.rut || null, nombre: pac.nombre || null, edad };
const medico = { rut: med.rut || null, nombre: med.nombre || null, matricula: med.matricula || null };

// 4. Detalle clínico: solo bloques con contenido (objetos o listas)
const detalle = {};
for (const [key, value] of Object.entries(obj(llm.detalle_clinico))) {
  if (value && typeof value === 'object') detalle[key] = value;
}

// 5. Auditoría humana
const hitl = Boolean(
  !respuestaValida ||
  decision.requiere_auditoria_humana ||
  score < 0.85 ||
  tipoCodigo === 'OTRO' ||
  destinoInvalido ||
  !paciente.nombre
);

const notif = obj(decision.notificacion_generada);
const notificacion = notif.canal && notif.mensaje
  ? { canal: String(notif.canal), mensaje: String(notif.mensaje) }
  : null;

return [{
  json: {
    documento_id: String(prep.json.documento_id),
    archivos: [
      { tipo_archivo: tipoArchivo, archivo_base64: String(archivoBase64), rol: 'documento_principal' },
    ],
    clasificacion: {
      tipo_documento: tipoCodigo,
      especialidad: clasificacion.especialidad || null,
      nivel_prioridad: prioridad,
      score_confianza_clasificacion: score,
    },
    datos_generales: {
      paciente,
      medico_solicitante: medico,
      diagnostico_principal: datos.diagnostico_principal || null,
      cie10_sugerido: datos.cie10_sugerido || null,
    },
    detalle_clinico: detalle,
    decision_enrutamiento: {
      destino_principal: destino,
      requiere_auditoria_humana: hitl,
      justificacion_enrutamiento: decision.justificacion_enrutamiento ||
        (respuestaValida ? null : 'La IA no devolvió un JSON válido'),
      notificacion_generada: notificacion,
    },
  },
}];

// Traduce la respuesta del backend al contrato del front: el body tal cual si fue 2xx, o
// { status: 'error', etapa, detalle } con el mismo código HTTP si falló.
const res = $input.first().json;
const code = Number(res.statusCode) || 502;
const body = res.body && typeof res.body === 'object' ? res.body : {};
if (code >= 200 && code < 300) {
  return [{ json: { statusCode: code, body } }];
}
const detail = body.detail ?? res.body ?? 'Error desconocido del backend';
return [{
  json: {
    statusCode: code,
    body: {
      status: 'error',
      etapa: code === 401 || code === 403 ? 'AUTENTICACION' : 'INGESTA_BACKEND',
      detalle: typeof detail === 'string' ? detail : JSON.stringify(detail),
    },
  },
}];
